// Minimal endless runner based on IDEA.md
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth || 800;
  const height = canvas.height = canvas.offsetHeight || 400;

  // Game state
  let frame = 0;
  let score = 0;
  const speed = 4; // world scroll speed

  // Player definition
  const player = {
    w: 40,
    h: 60,
    x: 80,
    y: height - 60,
    vy: 0,
    gravity: 0.8,
    jumpStrength: -15,
    sliding: false,
    slideTimer: 0,
    update() {
      // apply gravity
      this.vy += this.gravity;
      this.y += this.vy;
      // floor collision
      const floor = this.sliding ? height - this.h / 2 : height - this.h;
      if (this.y > floor) {
        this.y = floor;
        this.vy = 0;
      }
      // slide duration
      if (this.sliding) {
        this.slideTimer--;
        if (this.slideTimer <= 0) this.sliding = false;
      }
    },
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.fillRect(this.x, this.y, this.w, this.sliding ? this.h / 2 : this.h);
    }
  };

  // Simple obstacle constructor
  function Obstacle(x, w, h) {
    this.x = x;
    this.w = w;
    this.h = h;
    this.y = height - h;
  }
  Obstacle.prototype.update = function() { this.x -= speed; };
  Obstacle.prototype.draw = function() {
    ctx.fillStyle = '#f00';
    ctx.fillRect(this.x, this.y, this.w, this.h);
  };

  const obstacles = [];
  function spawnObstacle() {
    const w = 30 + Math.random() * 40;
    const h = 30 + Math.random() * 60;
    const x = width + w;
    obstacles.push(new Obstacle(x, w, h));
  }

  // Input handling
  document.addEventListener('keydown', e => {
    if (e.code === 'Space' && player.vy === 0) {
      player.vy = player.jumpStrength;
    } else if (e.code === 'ArrowDown' && !player.sliding && player.vy === 0) {
      player.sliding = true;
      player.slideTimer = 30; // frames
    }
  });

  // Collision detection
  function checkCollision(ob) {
    const pw = player.w;
    const ph = player.sliding ? player.h / 2 : player.h;
    const px = player.x;
    const py = player.y;
    return !(px + pw < ob.x || px > ob.x + ob.w || py + ph < ob.y || py > ob.y + ob.h);
  }

  // Game loop
  function loop() {
    frame++;
    // clear
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, width, height);

    // background parallax (simple gray bands)
    ctx.fillStyle = '#222';
    ctx.fillRect(0, height - 20, width, 20);

    // update player
    player.update();
    player.draw();

    // spawn obstacles periodically
    if (frame % 90 === 0) spawnObstacle();

    // update & draw obstacles, remove off‑screen
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const ob = obstacles[i];
      ob.update();
      ob.draw();
      if (ob.x + ob.w < 0) obstacles.splice(i, 1);
      else if (checkCollision(ob)) {
        // Game over – stop the loop
        ctx.fillStyle = '#ff0';
        ctx.font = '30px sans-serif';
        ctx.fillText('Game Over', width / 2 - 80, height / 2);
        return; // exit without requesting another frame
      }
    }

    // score display
    score = Math.floor(frame / 10);
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + score, 10, 20);

    requestAnimationFrame(loop);
  }

  // start
  requestAnimationFrame(loop);
})();
